//! libtorrent FFI: the flat C ABI wrapper's declarations, pre-generated by
//! bindgen and committed with the crate (ADR-002). The build only includes them;
//! `build.rs` checks that they still cover every declaration of
//! `wrapper/libtorrent_wrapper.h`.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]

include!("defines.rs");
include!("bindings.rs");

pub use defines::*;

// Compile-time version assertions: each pinned version string must encode to the
// pinned number, and the C++ probes assert those same numbers against the
// sources the build actually fetched.
const _: () =
    assert!(LIBTORRENT_VERSION_NUM == defines::version_num(LIBTORRENT_VERSION, [10000, 100, 1]));
const _: () = assert!(BOOST_VERSION_NUM == defines::version_num(BOOST_VERSION, [100000, 100, 1]));
